// Remove repeated subjects before platforms and vegetation are laid out.
const merged=new Set(['forest-light','forest-pond','meadow-cut','city-generalist','lake-nutrients','beach-wave','wadden-salt']);
export function activeHabitatBoards(h){return h.id==='farmland'?[]:h.boards.filter(b=>!merged.has(b.id)).map(b=>{
 if(b.id==='city-ground')return {...b,id:'city-hive',x:-22,z:0,title:'Der Garten · Blüten und Bienenvolk',body:'Im eingezäunten Vorgarten steht eine imkerliche Bienenbeute. Beobachte mit dem Fernglas eine Honigbiene an den Gartenblüten und auf ihrem Rückflug zum Stock. Mit der Lupe bestimmst du die Blütenpflanzen. Ein Besuch liefert Nahrung; erst Pollenübertragung zwischen unterschiedlichen Pflanzen derselben Art belegt hier die Bestäubungsbeziehung. Das Sammelgut wird tatsächlich zum Stock gebracht.',question:'Verfolge dieselbe Sammlerin. Welche Pflanze besucht sie, und wohin bringt sie ihre Nahrung?',concept:'Mutualismus · Pollenübertragung · Arbeitsteilung im Bienenvolk',source:'https://deutscherimkerbund.de/damit-aus-blueten-fruechte-werden/',feature:'hive'};
 if(b.id==='forest-birds')return {...b,body:b.body+' In einigen benachbarten Bäumen befinden sich Astlöcher und kugelige Eichhörnchenkobel. Beobachte ein Eichhörnchen beim Klettern und bei seiner Ruhephase. Ein Kobel ist ein gebautes Nest; ein Astloch ist eine Baumhöhle.',question:'Vergleiche Nahrungssuche, Klettern und Ruhen. Welche Baumstrukturen werden genutzt?'};
 if(b.id==='lake-predator')return {...b,body:b.body+' Am Ruhefelsen wechseln Kormorane zwischen Fischsuche im Wasser und Rast mit ausgebreiteten Flügeln. Diese Trocknungshaltung ist keine Flugbewegung.',question:'Verfolge einen Kormoran vom Wasser zum Felsen. Welche Tätigkeit folgt auf das Tauchen?'};
 if(b.id==='forest-deadwood')return {...b,question:'Untersuche den liegenden Stamm neben der Plattform. Was ist sichtbar, was lässt sich nur erschließen?'};
 if(b.id==='meadow-mouse')return {...b,question:'Finde mit dem Fernglas eine Feldmaus im Gras und einen jagenden Greifvogel. Beobachte Suchen, Angriff und Flucht.'};
 if(b.id==='lake-layer')return {...b,body:b.body+' Nährstoffeinträge können die Algenproduktion steigern. Der Abbau absinkender Biomasse verbraucht Sauerstoff. Die Abbildung erklärt einen tiefen See; das flache Modellgewässer zeigt keine gemessene Temperaturschichtung.'};
 if(b.id==='beach-strandline')return {...b,body:'Meer und Land sind am Spülsaum über angespülte organische Reste verbunden. Wirbellose nutzen diese Reste; Strandvögel fressen die Tiere. Sanderling und Sandregenpfeifer unterscheiden sich in Suchtechnik und erreichbarer Nahrung. Auf der offenen Strandfläche kannst du Laufpausen und Nahrungssuche vergleichen. Strandreinigung würde Nahrungs- und Deckungsressourcen entfernen.',question:'Vergleiche zwei Strandvögel: Wo und wie suchen sie Nahrung?'};
 if(b.id==='city-roof')return {...b,question:'Beobachte einen Mauersegler im Luftraum über den Häusern. Warum braucht er zusätzlich eine Gebäudenische? Ein Brutvorgang wird hier nicht simuliert.'};
 if(b.id==='wadden-hidden')return {...b,body:'Viel Wattfauna bleibt im Sediment verborgen. An den markierten Bodenproben neben dem Bohlenweg kannst du unterschiedliche Tiefen untersuchen und freigelegte Tiere mit dem Fernglas bestimmen. Wattwürmer nutzen organische Sedimentbestandteile; Muscheln filtrieren im Wasser suspendierte Nahrung. Beide sind Beute von Vögeln und Krebsen.',question:'Lege an der Probenstelle eine Muschel und einen Wurm frei. Vergleiche Aufenthaltsort und Ernährungsweise.'};
 return {...b};
 });}

export function boardDiagramKind(b){if(b.intro)return null;if(b.habitat==='forest'&&(b.station||b.id.startsWith('layer-')))return 'forest';if(b.id==='city-hive'||b.feature==='flowers')return 'pollination';if(b.id==='lake-layer')return 'lake';if(b.habitat==='saltmarsh'||b.id==='wadden-tide')return 'tide';if(b.id==='wadden-hidden')return 'sediment';if(b.id==='forest-deadwood')return 'decomposition';if(b.feature==='water'||b.id==='meadow-mouse'||b.id==='station-farmland')return 'foodweb';if(b.feature==='pond'||b.id.startsWith('pond-'))return 'pond';return 'habitat';}
const arrow=(x1,y1,x2,y2)=>`<path d="M${x1},${y1} L${x2},${y2}" fill="none" stroke="#75856c" stroke-width="2" marker-end="url(#board-arrow)"/>`;
const label=(x,y,text)=>`<text x="${x}" y="${y}" font-size="13" fill="#304a3c">${text}</text>`;
const box=(x,y,w,text)=>`<rect x="${x}" y="${y}" width="${w}" height="36" rx="5" fill="#eef0e1" stroke="#aab697"/>${label(x+10,y+23,text)}`;
export function boardIllustration(b){const kind=boardDiagramKind(b);if(!kind||kind==='habitat')return '';let content='',caption='';
 if(kind==='forest'){content='<path d="M55 191V58M49 191V69M82 191V63" stroke="#827257" stroke-width="8"/><ellipse cx="62" cy="49" rx="47" ry="28" fill="#748863"/><path d="M17 157Q41 113 75 153T120 160" fill="#8da173"/><path d="M18 180L31 158L40 180M85 180L99 156L110 180" stroke="#71815a" fill="none" stroke-width="4"/><path d="M15 191H135" stroke="#777251" stroke-width="8"/>'+['Baumschicht · Meisen im Kronenraum','Strauchschicht · Hasel, Deckung','Krautschicht · Farn, Blütenpflanzen','Moos / Streu · Detritus und Bodenfauna','Wurzelschicht · unterirdisches Gefüge'].map((t,i)=>label(155,45+i*36,t)).join('');caption='Die Schichten sind über Licht, Wasser und Nahrung verbunden. Die Wurzelschicht wird schematisch erklärt.';}
 if(kind==='pollination'){content=box(15,20,151,'Blütenpflanze A')+box(354,20,151,'Pflanze B · gleiche Art')+box(191,117,142,'Biene / Hummel')+arrow(94,58,239,116)+arrow(294,116,431,59)+label(18,83,'Nektar / Pollen → Nahrung')+label(311,83,'Pollen → mögliche Befruchtung')+label(175,175,'Honigbiene: Sammelgut zum Volk');caption='Ein Blütenbesuch ist noch kein Bestäubungsnachweis. Entscheidend ist die passende Pollenübertragung.';}
 if(kind==='lake'){content='<rect x="20" y="15" width="220" height="51" fill="#9dbabc"/><rect x="20" y="66" width="220" height="43" fill="#71979c"/><rect x="20" y="109" width="220" height="70" fill="#527580"/>'+label(259,43,'Epilimnion · warm, durchmischt')+label(259,91,'Metalimnion · Temperaturgradient')+label(259,147,'Hypolimnion · kaltes Tiefenwasser')+arrow(128,20,128,173)+label(25,204,'Licht nimmt ab · Abbau kann Sauerstoff verbrauchen');caption='Schema eines tiefen Sees im Sommer. Die kleinen Teiche und das flache Spielgewässer besitzen diese Schichtung nicht zwangsläufig.';}
 if(kind==='tide'){content='<path d="M15 176L172 162L355 104L510 61V204H15Z" fill="#b7b28b"/><path d="M15 135H280M15 91H390" stroke="#74989b" stroke-width="4" stroke-dasharray="7 5"/>'+label(20,39,'Watt / Priel')+label(186,39,'Untere Salzwiese')+label(365,39,'Obere Salzwiese')+label(24,124,'Ebbe')+label(24,81,'Flut')+label(181,183,'Queller / Strandflieder')+label(346,137,'Rotschwingel / Strandquecke');caption='Geländehöhe verändert Überflutung und Salzstress. Bei Flut weichen Watvögel auf trockene Rastplätze aus.';}
 if(kind==='sediment'){content='<rect x="20" y="65" width="210" height="135" fill="#beb298"/><path d="M20 65H230" stroke="#7a8373" stroke-width="4"/><path d="M100 71V177Q125 197 152 177V71" fill="none" stroke="#927458" stroke-width="8"/><ellipse cx="53" cy="96" rx="20" ry="11" fill="#656a59"/>'+label(249,81,'Oberfläche · Spuren, Biofilm')+label(249,118,'Flach eingegraben · Muscheln')+label(249,175,'Bodenröhre · Wattwurm')+label(25,40,'Bodenprobe: Oberfläche → 35 cm');caption='Schematischer Querschnitt. Die Tiere werden erst durch eine Bodenprobe sichtbar; Einbautiefen sind im Spiel vereinfacht.';}
 if(kind==='foodweb'){const fish=b.habitat==='lake';content=box(20,24,148,fish?'Algen / Pflanzen':'Gräser / Kräuter')+box(203,24,142,fish?'Kleine Fische':'Feldmaus')+box(385,24,112,fish?'Hecht':'Turmfalke')+arrow(170,42,201,42)+arrow(347,42,383,42)+label(25,116,'Pfeile: Nahrung / Energie → Konsument')+arrow(430,65,281,158)+label(130,184,'Prädation beeinflusst die Beute · Ressourcen begrenzen Wachstum');caption='Eine Nahrungskette ist ein Ausschnitt aus einem Netz. Der Beobachtungsauftrag zeigt eine Begegnung, keine gemessene Lotka–Volterra-Kurve.';}
 if(kind==='decomposition'){content=box(14,32,129,'Laub / Totholz')+box(191,32,150,'Bodentiere / Pilze')+box(385,32,126,'Mineralstoffe')+arrow(145,49,189,49)+arrow(343,49,383,49)+arrow(448,71,279,145)+box(198,149,151,'Pflanzenaufnahme')+label(35,114,'Stoffe zirkulieren · Energie wird schließlich als Wärme abgegeben');caption='Bodentiere zerkleinern Material; Pilze und Mikroorganismen bauen es ab. Diese Aufgaben sind verschieden.';}
 if(kind==='pond'){content='<path d="M20 105L163 145L389 170L510 99V205H20Z" fill="#aaa381"/><path d="M95 124H478V145Q270 195 95 124" fill="#86a7a4"/><path d="M109 130V60M119 134V72M130 138V56" stroke="#75886a" stroke-width="5"/><ellipse cx="250" cy="131" rx="30" ry="7" fill="#7c9165"/>'+label(17,31,'Ufer / Röhricht')+label(207,31,'Schwimmblattzone')+label(382,31,'Tauchblattzone')+label(125,190,'Amphibien · Wirbellose · in zwei Waldteichen auch Fische');caption='Räumliche Uferzonen sind von thermischen Tiefenschichten zu unterscheiden.';}
 return `<figure class="board-figure"><svg viewBox="0 0 535 222" role="img" aria-label="${kind==='forest'?'Schichten des Waldes':kind==='pollination'?'Pollenübertragung zwischen Pflanzen':kind==='lake'?'Thermische Schichtung eines tiefen Sees':kind==='tide'?'Geländehöhe und Überflutung':kind==='sediment'?'Wattboden im Querschnitt':kind==='foodweb'?'Nahrungskette und Rückwirkung':kind==='pond'?'Uferzonen am Teich':'Stoffkreislauf'}"><defs><marker id="board-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#75856c"/></marker></defs>${content}</svg><figcaption>${caption}</figcaption></figure>`;
}
